declare(strict_types=1);
namespace OCA\Mcp\Tests\Integration\Mail;
use OCA\Mcp\Tests\Integration\IntegrationTestCase;
use PHPUnit\Framework\Attributes\Group;
#[Group('mail')]
final class McpMailContentTest extends IntegrationTestCase {
    private function proof(string $mode):array {$r=MailActor::run(MailActor::ALICE,'content-native',['mode'=>$mode]);self::assertArrayNotHasKey('fixture_error',$r,json_encode($r));self::assertTrue($r['implementation_available'],'The closed bounded native reader must be installed.');return $r;}
    public function testOwnedServiceRequiresCurrentVisibleSourceAndFence():void {$r=$this->proof('service_raw');self::assertTrue($r['accepted'],json_encode($r));self::assertTrue($r['integrity']);self::assertTrue($r['foreign_refused']);self::assertTrue($r['revoked_refused']);}
    public function testPendingQuarantinePrecedesNetworkAndChangedSourceCannotReturnBytes():void {foreach(['service_quarantined','service_changed'] as $mode){$r=$this->proof($mode);self::assertFalse($r['accepted'],json_encode($r));self::assertSame($mode==='service_quarantined'?0:1,$r['connections']);self::assertSame(0,$r['writes']);}}
    public function testLargeEncodedPartListsWithoutBodiesAndDecodesExact25MiB():void {$r=$this->proof('service_list_large');self::assertTrue($r['accepted'],json_encode($r));self::assertSame(0,$r['bodies']);$r=$this->proof('service_part_large');self::assertTrue($r['accepted'],json_encode($r));self::assertTrue($r['integrity']);self::assertSame(1,$r['bodies']);self::assertSame(0,$r['writes']);}
    public function testLyingMetadataAndDecodedOverflowRefuseBeforeExport():void {foreach(['service_part_over','service_crypto_lie'] as $mode){$r=$this->proof($mode);self::assertFalse($r['accepted'],$mode);self::assertSame(0,$r['writes']);}}
    public function testDraftRevisionBindsRawHeadersAndRetainsCompositionManifest():void {$r=$this->proof('service_draft_revision');self::assertTrue($r['accepted'],json_encode($r));self::assertTrue($r['revision_changed']);self::assertTrue($r['manifest_retained']);self::assertSame(0,$r['writes']);}
    public function testIndexDoesNotReadAttachmentsAndDraftRequiresLiveFlag():void {$r=$this->proof('service_index');self::assertTrue($r['accepted'],json_encode($r));self::assertSame(1,$r['bodies']);$r=$this->proof('service_draft');self::assertTrue($r['accepted'],json_encode($r));self::assertTrue($r['draft_headers']);$r=$this->proof('service_not_draft');self::assertFalse($r['accepted']);self::assertSame(0,$r['bodies']);}
    public function testBoundedDisplayReadsSmallTextWithoutLargeAttachmentBody():void {$r=$this->proof('service_body');self::assertTrue($r['accepted'],json_encode($r));self::assertTrue($r['display_body']);self::assertSame(1,$r['bodies']);self::assertSame(0,$r['writes']);}
    public function testDisplayBodyActualDecodedLimitRefusesLyingMetadata():void {$r=$this->proof('service_body_over');self::assertFalse($r['accepted']);self::assertSame(1,$r['bodies']);self::assertSame(0,$r['writes']);}
    public function testExactOpaqueBytesAndLateUidDoNotMarkSeen():void {foreach(['raw','uid_after','crypto_raw'] as $mode){$r=$this->proof($mode);self::assertTrue($r['accepted'],$mode);self::assertTrue($r['integrity']);self::assertSame(1,$r['connections']);self::assertSame(0,$r['writes']);}}
    public function testAbsoluteDeadlineInterruptsSlowDripBeforeLineOrLiteralCompletes():void {foreach(['slow_line','slow_literal'] as $mode){$r=$this->proof($mode);self::assertFalse($r['accepted'],$mode);self::assertGreaterThanOrEqual(16,$r['elapsed'],$mode);self::assertLessThan(19,$r['elapsed'],$mode);self::assertSame(1,$r['connections']);self::assertSame(0,$r['writes']);}}
    public function testTlsContentPreservesExactLateUidBytesAndInterruptsSlowLineAndLiteral():void {foreach(['tls_uid_after','tls_slow_line','tls_slow_literal'] as $mode){$r=$this->proof($mode);self::assertSame($mode==='tls_uid_after',$r['accepted'],json_encode($r));self::assertSame(1,$r['tls_connections']);self::assertSame(1,$r['connections']);self::assertSame(0,$r['writes']);if($mode==='tls_uid_after')self::assertTrue($r['integrity']);else {self::assertGreaterThanOrEqual(16,$r['elapsed']);self::assertLessThan(19,$r['elapsed']);}}}
    public function testWireFaultsDoNotReturnPartialBytesOrRetry():void {foreach(['huge_literal','huge_line','wrong_uid','duplicate_uid','missing_tag','negative_tag','generation','generation_during','timeout','unsolicited_structure'] as $mode){$r=$this->proof($mode);self::assertFalse($r['accepted'],$mode);self::assertSame(1,$r['connections'],$mode);self::assertSame(0,$r['writes']);self::assertLessThanOrEqual(1,$r['fetches']);}}
    public function testManifestNeverFetchesBodiesAndRejectsUnboundedTrees():void {foreach(['manifest','deep_tree','many_parts','many_params'] as $mode){$r=$this->proof($mode);self::assertSame($mode==='manifest',$r['accepted'],$mode);self::assertSame(0,$r['bodies']);self::assertSame(0,$r['writes']);}}
}
